"""Figures for derived_8.4-formal-eval-2.0-ece (generated by the report notebook).

- temporal: per-config seed boxplots (R2), paired per-seed difference plots for
  headline comparisons, delta-source robustness bars per strategy.
- spatial: per-station pair scatter (A vs B, identity line, "k of 5 stations" win
  annotation), per-station bars with seed error bars for 5 ECE stations, and
  spatial seed boxplots.
"""

from __future__ import annotations

from pathlib import Path

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

from .stats import seed_summary

HEADLINE_PAIRS = [
    ("Clustering_V0_Full_k2_c0_0_c1_10", "Global_Single_54"),
    ("Clustering_Backbone54_k2_c0_10_c1_10", "Global_Single_54"),
    ("Clustering_V0_Full_k2_c0_0_c1_10", "Baseline_V0_50"),
    ("Clustering_Backbone54_k2_c0_10_c1_10", "Baseline_V0_50"),
    ("Clustering_V0_Full_k2_c0_0_c1_10", "Trained_Gating_k2_c0_5_c1_10"),
    ("Clustering_Backbone54_k2_c0_10_c1_10", "Trained_Gating_k2_c0_5_c1_10"),
]


def _label(config_id: str, cfg_frame: pd.DataFrame) -> str:
    row = cfg_frame[cfg_frame["config_id"] == config_id]
    if row.empty:
        return config_id
    label = str(row.iloc[0]["config_label"])
    return label if len(label) <= 42 else config_id


def plot_seed_boxplot(seed_df: pd.DataFrame, cfg_frame: pd.DataFrame, out_dir: Path,
                      prefix: str = "temporal", metric: str = "r2", figsize=(16, 6)) -> Path:
    """Per-config boxplot of the per-seed metric (temporal or spatial)."""
    order = (
        seed_df.groupby("config_id")[metric].median()
        .sort_values(ascending=False).index.tolist()
    )
    fig, ax = plt.subplots(figsize=figsize)
    data = [seed_df.loc[seed_df["config_id"] == c, metric].dropna() for c in order]
    ax.boxplot(data, tick_labels=[_label(c, cfg_frame) for c in order], showmeans=True)
    title_target = "temporal test set" if prefix == "temporal" else "5 in-situ ECE stations"
    ax.set_title(f"Per-seed {metric.upper()} by configuration ({title_target}, 30 seeds)")
    ax.set_ylabel(metric.upper())
    ax.tick_params(axis="x", rotation=90)
    fig.tight_layout()
    path = out_dir / f"{prefix}_seed_boxplot_{metric}.png"
    fig.savefig(path, dpi=150)
    plt.close(fig)
    return path


def plot_paired_differences(seed_df: pd.DataFrame, cfg_frame: pd.DataFrame, out_dir: Path,
                            pair: tuple[str, str], prefix: str = "paired_diff", metric: str = "r2") -> Path:
    """Per-seed paired difference (A - B) with 95% t-CI for one headline pair."""
    a, b = pair
    sub = seed_df[seed_df["config_id"].isin([a, b])]
    pa = sub[sub["config_id"] == a].set_index("seed")[metric].sort_index()
    pb = sub[sub["config_id"] == b].set_index("seed")[metric].sort_index()
    common = pa.index.intersection(pb.index)
    diff = pa.loc[common].to_numpy() - pb.loc[common].to_numpy()
    s = seed_summary(pd.Series(diff))
    fig, ax = plt.subplots(figsize=(7, 5))
    ax.scatter(range(len(diff)), np.sort(diff), s=28, alpha=0.8)
    ax.axhline(0, color="grey", lw=1)
    ax.axhline(s["mean"], color="tab:red", lw=1.5, label=f"mean diff {s['mean']:.5f}")
    ax.axhline(s["ci_low"], color="tab:red", ls="--", lw=1, label=f"95% CI [{s['ci_low']:.5f}, {s['ci_high']:.5f}]")
    ax.axhline(s["ci_high"], color="tab:red", ls="--", lw=1)
    ax.set_title(f"Per-seed {metric.upper()} difference\n{_label(a, cfg_frame)} - {_label(b, cfg_frame)}")
    ax.set_xlabel("seed rank")
    ax.set_ylabel(f"$\\Delta$ {metric.upper()}")
    ax.legend(fontsize=8)
    fig.tight_layout()
    path = out_dir / f"{prefix}_{metric}_{a}_vs_{b}.png"
    fig.savefig(path, dpi=150)
    plt.close(fig)
    return path


DELTA_SOURCE_COLORS = {
    "test": "#1f77b4",  # tab:blue
    "val": "#ff7f0e",   # tab:orange
    "none": "#2ca02c",  # tab:green
}

DELTA_SOURCE_LABELS = {
    "test": "Test-selected",
    "val": "Val-selected",
    "none": "None (no delta)",
}


def plot_delta_robustness(temp_df: pd.DataFrame, spat_df: pd.DataFrame,
                          cfg_frame: pd.DataFrame, out_dir: Path, metric: str = "r2") -> Path:
    """Delta-source robustness: per strategy, metric mean +/- std for test/val/none with consistent colors."""
    strategies = sorted(cfg_frame["strategy_name"].unique())
    strategies = [s for s in strategies if s not in ("Global_Single",)]
    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(18, 6), sharey=True)
    width = 0.25
    source_order = ("test", "val", "none")

    # Axis 1: Temporal
    ax1.grid(axis="y", linestyle="--", alpha=0.4, zorder=0)
    for i, strategy in enumerate(strategies):
        rows = cfg_frame[cfg_frame["strategy_name"] == strategy]
        for j, source in enumerate(source_order):
            cid = rows[rows["delta_source"] == source]["config_id"]
            if cid.empty:
                continue
            vals = temp_df.loc[temp_df["config_id"] == cid.iloc[0], metric].dropna()
            if vals.empty:
                continue
            s = seed_summary(vals)
            x = i + (j - 1) * width
            ax1.bar(x, s["mean"], width=width, yerr=s["std"] if s["std"] == s["std"] else 0,
                    color=DELTA_SOURCE_COLORS[source], edgecolor="black", linewidth=0.5,
                    label=DELTA_SOURCE_LABELS[source] if i == 0 else None, capsize=3, zorder=3)
    ax1.set_xticks(range(len(strategies)))
    ax1.set_xticklabels(strategies, rotation=30, ha="right")
    ax1.set_ylabel(f"Temporal {metric.upper()} (mean ± std over seeds)")
    ax1.set_title(f"Temporal Delta-Source Robustness ({metric.upper()})")
    ax1.legend(title="Delta Source", loc="upper right")

    # Axis 2: Spatial (ECE)
    ax2.grid(axis="y", linestyle="--", alpha=0.4, zorder=0)
    for i, strategy in enumerate(strategies):
        rows = cfg_frame[cfg_frame["strategy_name"] == strategy]
        for j, source in enumerate(source_order):
            cid = rows[rows["delta_source"] == source]["config_id"]
            if cid.empty:
                continue
            vals = spat_df.loc[spat_df["config_id"] == cid.iloc[0], metric].dropna()
            if vals.empty:
                continue
            s = seed_summary(vals)
            x = i + (j - 1) * width
            ax2.bar(x, s["mean"], width=width, yerr=s["std"] if s["std"] == s["std"] else 0,
                    color=DELTA_SOURCE_COLORS[source], edgecolor="black", linewidth=0.5,
                    label=DELTA_SOURCE_LABELS[source] if i == 0 else None, capsize=3, zorder=3)
    ax2.set_xticks(range(len(strategies)))
    ax2.set_xticklabels(strategies, rotation=30, ha="right")
    ax2.set_ylabel(f"Spatial (ECE) {metric.upper()} (mean ± std over seeds)")
    ax2.set_title(f"Spatial (ECE) Delta-Source Robustness ({metric.upper()})")
    ax2.legend(title="Delta Source", loc="upper right")

    fig.tight_layout()
    path = out_dir / f"delta_robustness_{metric}.png"
    fig.savefig(path, dpi=150)
    plt.close(fig)
    return path


def plot_spatial_pair(per_station_df: pd.DataFrame, cfg_frame: pd.DataFrame, out_dir: Path,
                      pair: tuple[str, str], metric: str = "r2") -> Path:
    """Spatial (ECE) per-station pair scatter: A vs B (per-station median over seeds),
    with identity line and 'A wins k of 5 stations' annotation."""
    a, b = pair
    med = (
        per_station_df.groupby(["config_id", "station"])[metric]
        .median().reset_index()
    )
    ma = med[med["config_id"] == a].set_index("station")[metric]
    mb = med[med["config_id"] == b].set_index("station")[metric]
    common = ma.index.intersection(mb.index)
    x = mb.loc[common].to_numpy()
    y = ma.loc[common].to_numpy()
    wins = int(np.sum(y > x))
    n = len(common)

    fig, ax = plt.subplots(figsize=(7, 7))
    lo = min(x.min(), y.min())
    hi = max(x.max(), y.max())
    pad = 0.05 * (hi - lo) if hi > lo else 0.1
    ax.plot([lo - pad, hi + pad], [lo - pad, hi + pad], color="grey", lw=1, ls="--")
    ax.scatter(x, y, s=70)
    for i, st in enumerate(common):
        clean_st = st.replace("_", " ")
        ax.annotate(clean_st, (x[i], y[i]), textcoords="offset points", xytext=(6, 6), fontsize=7)
    ax.set_xlabel(f"{_label(b, cfg_frame)} — {metric.upper()}")
    ax.set_ylabel(f"{_label(a, cfg_frame)} — {metric.upper()}")
    ax.set_title(f"ECE Spatial per-station {metric.upper()}: {_label(a, cfg_frame)} wins {wins} of {n} stations")
    fig.tight_layout()
    path = out_dir / f"spatial_pair_{metric}_{a}_vs_{b}.png"
    fig.savefig(path, dpi=150)
    plt.close(fig)
    return path


def plot_spatial_station_bars(per_station_df: pd.DataFrame, cfg_frame: pd.DataFrame,
                             out_dir: Path, config_id: str, metric: str = "r2") -> Path:
    """Per-station ECE metric with seed error bars for one config."""
    sub = per_station_df[per_station_df["config_id"] == config_id]
    stations = sorted(sub["station"].unique())
    fig, ax = plt.subplots(figsize=(10, 5))
    means, stds = [], []
    for st in stations:
        vals = sub.loc[sub["station"] == st, metric].dropna()
        s = seed_summary(vals)
        means.append(s["mean"])
        stds.append(s["std"] if s["std"] == s["std"] else 0.0)
    ax.bar(range(len(stations)), means, yerr=stds, capsize=4)
    ax.set_xticks(range(len(stations)))
    ax.set_xticklabels([s.replace("_", " ") for s in stations], rotation=30, ha="right")
    ax.set_ylabel(f"ECE Spatial {metric.upper()}")
    ax.set_title(f"ECE per-station {metric.upper()} (mean ± std over seeds): {_label(config_id, cfg_frame)}")
    fig.tight_layout()
    path = out_dir / f"spatial_station_bars_{metric}_{config_id}.png"
    fig.savefig(path, dpi=150)
    plt.close(fig)
    return path


